function addToDigits(digits: number[], k: number): number[] {
  const kd = String(k).split("").map(Number);
  let i = digits.length - 1, j = kd.length - 1, carry = 0;
  const out: number[] = [];
  while (i >= 0 || j >= 0 || carry) {
    const sum = (i >= 0 ? digits[i--] : 0) + (j >= 0 ? kd[j--] : 0) + carry;
    out.push(sum % 10);
    carry = sum >= 10 ? 1 : 0;
  }
  return out.reverse();
}

