class Solution:
    def addToDigits(self, digits: List[int], k: int) -> List[int]:
        kd = [int(c) for c in str(k)]
        i, j, carry = len(digits) - 1, len(kd) - 1, 0
        out = []
        while i >= 0 or j >= 0 or carry:
            s = carry
            if i >= 0:
                s += digits[i]
                i -= 1
            if j >= 0:
                s += kd[j]
                j -= 1
            out.append(s % 10)
            carry = s // 10
        return out[::-1]

