function addToDigits(digits: number[], k: number): number[] {
  const out: number[] = [];
  let i = digits.length - 1, carry = k;
  while (i >= 0 || carry > 0) {
    if (i >= 0) carry += digits[i--];
    out.push(carry % 10);
    carry = Math.floor(carry / 10);
  }
  return out.reverse();
}

